    internal bool Running(){return FindRunning().Length>0;}
    internal Process[] FindRunning(){var entries=new List<Process>();foreach(var p in Process.GetProcessesByName(Path.GetFileNameWithoutExtension(Executable))){try{if(p.SessionId==Process.GetCurrentProcess().SessionId&&String.Equals(p.MainModule.FileName,Executable,StringComparison.OrdinalIgnoreCase))entries.Add(p);else p.Dispose();}catch(System.ComponentModel.Win32Exception){p.Dispose();throw new InvalidOperationException("无法核验正在运行的 Codex 进程，请先保存工作并退出 Codex。");}catch(InvalidOperationException){p.Dispose();}}return entries.ToArray();}
