internal static class WebSocketStartup {
    internal static Dictionary<string,object> Prepare(WebSocketSettings settings,string install,Action<string> log){var proxy=settings.Resolve();if(proxy==null)throw new InvalidOperationException("尚未配置 WebSocket 代理。请启用 HTTP 代理，或完整填写独立 WS 地址。");var app=WebSocketApp.Inspect(install);SavePrepared(settings,WebSocketSettings.SettingsPath,app.Version);if(log!=null)log("WebSocket 线路修复已准备："+settings.Description+"。请通过本工具启动 Codex，真实连接尚未验证。");return new Dictionary<string,object>{{"state","prepared"},{"summary","WebSocket 线路修复已准备；通过本工具启动后再验证"},{"appVersion",app.Version},{"executable",app.Executable},{"dotHost",app.DotHost},{"proxy",proxy.Authority}};}
    internal static void SavePrepared(WebSocketSettings settings,string path,string version){var marker=path+".prepared";var previous=File.Exists(path)?Convert.ToBase64String(File.ReadAllBytes(path)):null;settings.Save(path);if(!File.Exists(marker))File.WriteAllText(marker,Core.Json.Serialize(new {previous=previous,appVersion=version}),new UTF8Encoding(false));}
    internal static Dictionary<string,object> Check(WebSocketSettings settings,Action<string> log){var result=new Dictionary<string,object>{{"proxyState","未检查"},{"websocketState","未验证"},{"modelState","未验证：尚未执行已登录模型线路诊断"},{"dotState","未验证：需重启后检查真实远程连接"}};var probe=new WebSocketSettings{websocketRepair=true,wsProxyHost=settings.wsProxyHost,wsProxyPort=settings.wsProxyPort,httpPort=settings.httpPort,httpHost=settings.httpHost};var proxy=probe.Resolve();result["effectiveProxy"]=proxy==null?"直连":probe.Description;try{if(proxy!=null){using(var client=WebSocketNetwork.Connect(proxy.Host,proxy.Port,3000)){}result["proxyState"]="端口可达；尚未证明支持 WebSocket";}else result["proxyState"]="直连检查，不使用显式代理";
            Exception last=null;foreach(var endpoint in new[]{"wss://echo.websocket.org/","wss://ws.postman-echo.com/raw"})try{if(log!=null)log("正在检查 WebSocket 线路："+new Uri(endpoint).Host);WebSocketNetwork.Echo(new Uri(endpoint),proxy,log);last=null;break;}catch(Exception ex){last=ex;if(log!=null)log("此测试站未完成："+ex.Message);}if(last!=null)throw last;result["websocketState"]="通过：握手及三次持续回显通过；不代表 Dot 已恢复";result["passed"]=true;}
        catch(Exception ex){result["passed"]=false;result["websocketState"]="未完成："+ex.Message;}
        var actual=Verify();result["dotState"]=Core.Value(actual,"summary","未验证");if(log!=null){log("代理检查："+result["proxyState"]);log("WebSocket 线路："+result["websocketState"]);log("模型回复："+result["modelState"]);log("Dot 远程连接："+result["dotState"]);}return result;}
    internal static Dictionary<string,object> ModelCheck(WebSocketSettings settings,string cli){
        if(String.IsNullOrWhiteSpace(cli)||!File.Exists(cli))throw new FileNotFoundException("尚未找到当前官方 CLI，请先刷新状态或准备官方独立 CLI。");
        var path=Path.GetFullPath(cli);var standalone=Path.Combine(CurrentModelSettings.CodexHome(),"packages","standalone")+Path.DirectorySeparatorChar;var store=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"WindowsApps")+Path.DirectorySeparatorChar;
        if(!path.StartsWith(standalone,StringComparison.OrdinalIgnoreCase)&&!path.StartsWith(store,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("只读模型线路检查仅支持已识别的官方 CLI。");
        var start=StartInfo(path,settings.HttpProxy);start.Arguments="doctor --network-only --json";start.CreateNoWindow=true;start.RedirectStandardOutput=true;start.RedirectStandardError=true;start.StandardOutputEncoding=Encoding.UTF8;start.StandardErrorEncoding=Encoding.UTF8;
        if(settings.httpPort==0)foreach(var key in new[]{"HTTP_PROXY","HTTPS_PROXY","ALL_PROXY","http_proxy","https_proxy","all_proxy"})start.EnvironmentVariables[key]="";
        using(var process=Process.Start(start)){var output=process.StandardOutput.ReadToEndAsync();var error=process.StandardError.ReadToEndAsync();if(!process.WaitForExit(45000)){process.Kill();process.WaitForExit();throw new IOException("模型线路只读诊断超时，已结束本次探针，不影响原对话。");}process.WaitForExit();var text=output.GetAwaiter().GetResult();var stderr=error.GetAwaiter().GetResult();
            Dictionary<string,object> data;try{data=Core.ReadJson(text);}catch{throw new IOException("当前 CLI 未返回支持的网络诊断结果，请更新 CLI 后重试。退出码："+process.ExitCode+(stderr.IndexOf("Access",StringComparison.OrdinalIgnoreCase)>=0?"；版本探针可能受权限限制":""));}
            return ParseModelReport(data);
        }
    }
    internal static Dictionary<string,object> ParseModelReport(Dictionary<string,object> data){object checksValue,wsValue;if(!data.TryGetValue("checks",out checksValue)||!(checksValue is Dictionary<string,object>)||!((Dictionary<string,object>)checksValue).TryGetValue("network.websocket_reachability",out wsValue)||!(wsValue is Dictionary<string,object>))throw new InvalidDataException("网络诊断缺少模型 WebSocket 检查项，不能确认成功。");var ws=(Dictionary<string,object>)wsValue;object detailValue;var details=ws.TryGetValue("details",out detailValue)?detailValue as Dictionary<string,object>:null;bool passed=Core.Value(ws,"status","")=="ok"&&Core.Value(details,"handshake result","").StartsWith("HTTP 101",StringComparison.Ordinal);return new Dictionary<string,object>{{"kind","model"},{"passed",passed},{"modelState",passed?"通过：官方 CLI 的已登录 WS 握手成功（独立探针，当前会话传输仍需日志确认）":"未通过：官方 CLI 的模型 WS 握手未完成，请查看诊断日志"},{"summary",passed?"模型 WebSocket 线路检查通过；未创建对话或发送任务":"模型 WebSocket 线路检查未通过"}};}
    internal static Dictionary<string,object> Verify(){
        if(!File.Exists(WebSocketSettings.StatePath))return new Dictionary<string,object>{{"state","unverified"},{"summary","未通过本工具启动；真实连接尚未验证"}};var state=Core.ReadJson(File.ReadAllText(WebSocketSettings.StatePath));if(!IsProcess(Core.Value(state,"pid","0"),Core.Value(state,"started","0"),Core.Value(state,"executable","")))return new Dictionary<string,object>{{"state","stopped"},{"summary","本工具启动的 Codex 已退出；下次启动后重新验证"}};
        DateTime since;if(!DateTime.TryParse(Core.Value(state,"launchedAt",""),null,System.Globalization.DateTimeStyles.RoundtripKind,out since))throw new InvalidDataException("启动记录缺少有效时间，请通过本工具重新启动后验证。");var root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Codex","Logs",DateTime.Now.ToString("yyyy"),DateTime.Now.ToString("MM"),DateTime.Now.ToString("dd"));var lines=new List<string>();
        if(Directory.Exists(root))foreach(var path in Directory.GetFiles(root,"*.log")){var info=new FileInfo(path);if(info.LastWriteTimeUtc<since.ToUniversalTime())continue;using(var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){stream.Position=Math.Max(0,stream.Length-512*1024);using(var reader=new StreamReader(stream)){string line;while((line=reader.ReadLine())!=null)lines.Add(line);}}}
        return ParseConnectionEvidence(lines,since);
    }
    internal static Dictionary<string,object> ParseConnectionEvidence(IEnumerable<string> lines,DateTime since){
        DateTime latest=DateTime.MinValue;string status="unverified",failure="";
        foreach(var line in lines){if(!Regex.IsMatch(line,@"host(?:Id|Kind)=durable\b"))continue;var stamp=Regex.Match(line,@"\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?Z");DateTime time;if(!stamp.Success||!DateTime.TryParse(stamp.Value,null,System.Globalization.DateTimeStyles.RoundtripKind,out time)||time.ToUniversalTime()<since.ToUniversalTime()||time.ToUniversalTime()<latest)continue;
            var transition=Regex.Match(line,@"(?:^|\s)(?:state|currentState|nextState|next)=(connected|disconnected|connecting|reconnecting|failed|error)\b");bool connected=transition.Success&&transition.Groups[1].Value=="connected"||Regex.IsMatch(line,@"(?:^|\s)initialized=true\b");bool failed=line.Contains("open_timeout")||line.Contains("websocket_error")||line.Contains("connection_failed");if(!transition.Success&&!connected&&!failed)continue;latest=time.ToUniversalTime();status=connected&&!failed?"connected":transition.Success&&transition.Groups[1].Value=="disconnected"?"disconnected":"unverified";failure=failed?(line.Contains("403")?"远程服务拒绝连接（HTTP 403），代理与登录状态需继续核对":"远程连接尚未建立，请查看 Codex 日志"):"";
        }
        return new Dictionary<string,object>{{"state",status},{"summary",status=="connected"?"Codex 重启后日志记录远程连接已建立；请再用 Dot 验证读取":failure.Length>0?failure:status=="disconnected"?"Codex 日志显示远程连接尚未建立；请从 Dot 发起只读检查后再验证":"已启动 Codex，尚未取得真实远程连接建立的证据"}};
    }
    internal static bool IsProcess(string id,string ticks,string path){int pid;long started;if(!Int32.TryParse(id,out pid)||!Int64.TryParse(ticks,out started))return false;try{using(var p=Process.GetProcessById(pid))return !p.HasExited&&p.StartTime.ToUniversalTime().Ticks==started&&String.Equals(p.MainModule.FileName,path,StringComparison.OrdinalIgnoreCase);}catch(ArgumentException){return false;}catch(InvalidOperationException){return false;}}
    internal static void Rollback(Action<string> log){Rollback(WebSocketSettings.SettingsPath,WebSocketSettings.StatePath,log);}
    internal static void Rollback(string path,string statePath,Action<string> log){
        if(File.Exists(statePath)){var state=Core.ReadJson(File.ReadAllText(statePath));if(IsProcess(Core.Value(state,"pid","0"),Core.Value(state,"started","0"),Core.Value(state,"executable","")))throw new InvalidOperationException("请先保存工作并退出由本工具启动的 Codex，再撤销线路修复。");File.Delete(statePath);}
        var marker=path+".prepared";if(!File.Exists(marker)){if(log!=null)log("没有需要撤销的 WebSocket 启动准备，现有设置保留。");return;}
        var saved=Core.ReadJson(File.ReadAllText(marker));object prior;if(saved.TryGetValue("previous",out prior)&&prior!=null)File.WriteAllBytes(path,Convert.FromBase64String((string)prior));else if(File.Exists(path))File.Delete(path);File.Delete(marker);if(File.Exists(path+".previous"))File.Delete(path+".previous");if(log!=null)log("已撤销 WebSocket 启动准备；HTTP 配置和官方文件未修改。原 Codex 图标保持原有启动方式。");
    }
    internal static ProcessStartInfo StartInfo(string executable,Uri proxy){var info=new ProcessStartInfo(executable){UseShellExecute=false,WorkingDirectory=Path.GetDirectoryName(executable)};info.EnvironmentVariables.Remove("ELECTRON_RUN_AS_NODE");if(proxy!=null){foreach(var key in new[]{"HTTP_PROXY","HTTPS_PROXY","http_proxy","https_proxy"})info.EnvironmentVariables[key]=proxy.AbsoluteUri;info.EnvironmentVariables["NODE_USE_ENV_PROXY"]="1";}var noProxy=info.EnvironmentVariables["NO_PROXY"]??info.EnvironmentVariables["no_proxy"]??"";var list=noProxy.Split(',').Where(x=>x.Trim().Length>0).Concat(new[]{"localhost","127.0.0.1","::1"}).Distinct(StringComparer.OrdinalIgnoreCase);info.EnvironmentVariables["NO_PROXY"]=info.EnvironmentVariables["no_proxy"]=String.Join(",",list);return info;}
    internal static async Task<Dictionary<string,object>> Launch(WebSocketSettings settings,string install){var app=WebSocketApp.Inspect(install);var processes=app.FindRunning();try{if(processes.Length>0)throw new InvalidOperationException("Codex 仍在运行，请先保存工作并通过关闭确认退出，再执行 WebSocket 线路修复。");}finally{foreach(var p in processes)p.Dispose();}var proxy=settings.Resolve();if(proxy==null)throw new InvalidOperationException("尚未配置 WS 使用的代理。");Process relay=null;bool launched=false;try{
            if(settings.Independent){var directory=Path.Combine(Core.Root,"Relay",Core.Version);Directory.CreateDirectory(directory);var exe=Path.Combine(directory,"CodexInitKitRelay.exe");if(!File.Exists(exe)||Core.Hash(exe)!=Core.Hash(Core.Exe))File.Copy(Core.Exe,exe,true);var start=new ProcessStartInfo(exe,"--ws-relay"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true};relay=Process.Start(start);relay.StandardInput.WriteLine(Core.Json.Serialize(new {http=settings.HttpProxy==null?"":settings.HttpProxy.AbsoluteUri,websocket=proxy.AbsoluteUri,dotHost=app.DotHost}));relay.StandardInput.Flush();var ready=relay.StandardOutput.ReadLineAsync();if(await Task.WhenAny(ready,Task.Delay(10000))!=ready)throw new IOException("本机 WS 转发组件未能及时启动；请检查安全软件提示。");var report=Core.ReadJson(await ready);proxy=new Uri("http://127.0.0.1:"+Core.Value(report,"port","0"));}
            var launchedAt=DateTime.UtcNow;var info=StartInfo(app.LaunchAlias,proxy);info.WorkingDirectory=Path.GetDirectoryName(app.Executable);using(var started=StartOfficial(info)){
                Process main=null;for(int attempt=0;attempt<60&&main==null;attempt++){await Task.Delay(250);foreach(var p in app.FindRunning()){if(p.MainWindowHandle!=IntPtr.Zero&&p.StartTime.ToUniversalTime()>=launchedAt.AddSeconds(-1))main=p;else p.Dispose();}}
                if(main==null)throw new IOException("已请求启动官方 Codex，但未能核验新主进程；线路尚未验证。");using(main){var state=new Dictionary<string,object>{{"pid",main.Id},{"launchAlias",app.LaunchAlias},{"started",main.StartTime.ToUniversalTime().Ticks},{"executable",app.Executable},{"appVersion",app.Version},{"launchedAt",launchedAt.ToString("o")},{"independent",settings.Independent}};if(relay!=null){relay.StandardInput.WriteLine(Core.Json.Serialize(state));relay.StandardInput.Flush();relay.StandardInput.Close();}File.WriteAllText(WebSocketSettings.StatePath,Core.Json.Serialize(state),new UTF8Encoding(false));launched=true;return new Dictionary<string,object>{{"state","launched"},{"summary","已通过本工具启动 Codex；WebSocket 实际连接仍待验证"},{"pid",main.Id}};}
            }
        }finally{if(relay!=null){if(!launched&&!relay.HasExited)relay.Kill();relay.Dispose();}}
    }
    internal static Process StartOfficial(ProcessStartInfo info){try{return Process.Start(info);}catch(System.ComponentModel.Win32Exception ex){throw new IOException("无法通过官方应用执行别名启动 Codex（Windows 错误码 "+ex.NativeErrorCode+"）："+DesktopLocalization.ExceptionText(ex),ex);}}
    internal static int RelayMain(){try{var input=Core.ReadJson(Console.ReadLine());var http=Core.Value(input,"http","");var ws=new Uri(Core.Value(input,"websocket",""));var host=Core.Value(input,"dotHost","");if(ws.Scheme!="http"||ws.UserInfo.Length>0||host!="codex-cloud-backend.chatgpt.com")return 64;var relayLog=Path.Combine(Core.Logs,"ws-relay-"+Process.GetCurrentProcess().Id+".log");var relayLogGate=new object();Uri original=http.Length==0?null:new Uri(http);if(original!=null&&(original.Scheme!="http"||original.UserInfo.Length>0))return 64;using(var relay=new WebSocketRelay(original,ws,host,message=>{lock(relayLogGate)File.AppendAllText(relayLog,DateTime.Now.ToString("HH:mm:ss")+" "+message+Environment.NewLine,new UTF8Encoding(false));})){relay.Start();Console.WriteLine(Core.Json.Serialize(new {port=relay.Port}));Console.Out.Flush();var ownerLine=Console.In.ReadLineAsync();if(Task.WhenAny(ownerLine,Task.Delay(30000)).GetAwaiter().GetResult()!=ownerLine)return 1;var line=ownerLine.Result;if(String.IsNullOrWhiteSpace(line))return 1;var owner=Core.ReadJson(line);while(IsProcess(Core.Value(owner,"pid","0"),Core.Value(owner,"started","0"),Core.Value(owner,"executable","")))Thread.Sleep(1000);}return 0;}catch(Exception ex){Console.Error.WriteLine("WebSocket 本机线路未完成："+ex.Message);return 1;}}
}
